import{_ as i,c as o,o as d,ag as t}from"./chunks/framework.DfL_BkQ-.js";const h=JSON.parse('{"title":"📦 Официальный модпак Manima","description":"","frontmatter":{},"headers":[],"relativePath":"info/modpack.md","filePath":"info/modpack.md"}'),c={name:"info/modpack.md"};function r(s,a,l,e,n,p){return d(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="📦-официальныи-модпак-manima" tabindex="-1">📦 Официальный модпак Manima <a class="header-anchor" href="#📦-официальныи-модпак-manima" aria-label="Permalink to &quot;📦 Официальный модпак Manima&quot;">​</a></h1><p>Мы создали идеальную сборку для игры на нашем сервере. Она не добавляет новых блоков (вы можете зайти и без неё), но она кардинально меняет <strong>ощущения от игры</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Зачем это нужно?</p><p>Эта сборка повышает FPS, добавляет голосовой чат, красивые анимации и прочие удобства.</p></div><h2 id="что-в-модпаке" tabindex="-1">Что в модпаке? <a class="header-anchor" href="#что-в-модпаке" aria-label="Permalink to &quot;Что в модпаке?&quot;">​</a></h2><div class="mod-grid"><div class="mod-card"><div class="icon">🎤</div><h3>Голосовой чат</h3><p>Plasmo Voice — разговаривай с игроками прямо на сервере.</p></div><div class="mod-card"><div class="icon">👋</div><h3>Эмоции</h3><p>Emotecraft — маши рукой, хлопай в ладоши или танцуй вместе с друзьями.</p></div><div class="mod-card"><div class="icon">🚀</div><h3>Оптимизация</h3><p>Sodium + Iris — твой FPS вырастет в 2-3 раза. Поддержка шейдеров включена.</p></div><div class="mod-card"><div class="icon">🗺️</div><h3>Карта мира</h3><p>Xaero&#39;s World Map — карта, чтобы не потеряться в нашем огромном мире.</p></div><div class="mod-card"><div class="icon">🔦</div><h3>Свет в руке</h3><p>LambDynamicLights — факел светится прямо в руке.</p></div><div class="mod-card"><div class="icon">➕</div><h3>И прочие</h3><p>3D скины, красивые частицы, плавный зум и плавные чанки.</p></div></div><h2 id="📥-как-установить" tabindex="-1">📥 Как установить? <a class="header-anchor" href="#📥-как-установить" aria-label="Permalink to &quot;📥 Как установить?&quot;">​</a></h2><p>Мы используем платформу <strong>Modrinth</strong>, потому что это удобно и безопасно.</p><h3 id="способ-1-xmcl-prism-modrinth-app" tabindex="-1">Способ 1: XMCL / Prism / Modrinth App <a class="header-anchor" href="#способ-1-xmcl-prism-modrinth-app" aria-label="Permalink to &quot;Способ 1: XMCL / Prism / Modrinth App&quot;">​</a></h3><p>Это самый надежный способ.</p><ol><li>Скачай нашу сборку (файл <code>.mrpack</code>) по кнопке ниже.</li><li>Открой свой лаунчер.</li><li>Нажми <strong>&quot;Добавить сборку&quot;</strong> -&gt; <strong>&quot;Импорт из файла&quot;</strong>.</li><li>Выбери скачанный файл. Готово!</li></ol><div style="text-align:center;margin:30px 0;"><a href="https://modrinth.com/" target="_blank" class="btn-download">Скачать файл сборки (.mrpack)</a></div><h3 id="способ-2-tlauncher-legacy" tabindex="-1">Способ 2: TLauncher / Legacy <a class="header-anchor" href="#способ-2-tlauncher-legacy" aria-label="Permalink to &quot;Способ 2: TLauncher / Legacy&quot;">​</a></h3><p>Если вы используете старые лаунчеры, установка чуть сложнее (вручную).</p><ol><li>Установи версию <strong>Fabric 1.21.8</strong>.</li><li>Скачай архив с модами (zip) по ссылке ниже.</li><li>Открой папку игры (обычно <code>%appdata%/.minecraft</code>).</li><li>Перекинь всё из архива в папку <code>mods</code>.</li></ol><div class="warning custom-block"><p class="custom-block-title">Внимание</p><p>Убедись, что ты удалил старые моды перед установкой новых, чтобы избежать конфликтов!</p></div>',15)])])}const v=i(c,[["render",r]]);export{h as __pageData,v as default};
